  save(s);
  console.log("file recorded", p);
  process.exit(0);
}
if (cmd === "add-command") {
  // raw json {command, exitCode, stdout, stderr, durationMs}
  const arg = process.argv.slice(3).join(" ");
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { command: arg }; }
  const s = load();
